class RegHwcfg2 extends Bundle {
  val rrid_transl       = UInt(16.W)
  val prio_entry        = UInt(16.W)
  def toUInt: UInt = Cat(rrid_transl, prio_entry)
}

object RegHwcfg2 {
  def apply(): RegHwcfg2 = {
    val init_val = Wire(new RegHwcfg2)
    init_val.prio_entry  := IopmpParams.prio_entry.U
    init_val.rrid_transl := IopmpParams.rrid_transl.U
    RegInit(init_val)
  }
}

val msi_en            = UInt(1.W)  // [WARL] Indicates whether the IOPMP triggers interrupt by MSI or wired interrupt
// ... toUInt encoding ...
def toUInt: UInt = Cat(rsv2, msidata, rsv1, stall_violation_en, msi_en, rs, ie, l)

when(io.regcfg.v && io.regcfg.rw && addrhit_errcfg) {
    val w = io.regcfg.din.asTypeOf(new RegErrcfg)
    reg_errcfg.l := reg_errcfg.l | w.l  // W1SS
    when(reg_errcfg.l === 0.U) {
      reg_errcfg.ie := w.ie
      reg_errcfg.rs := w.rs
      reg_errcfg.msi_en := w.msi_en  // WARL — NO gating on HWCFG2.msi_en
      reg_errcfg.stall_violation_en := w.stall_violation_en
      reg_errcfg.msidata := w.msidata  // WARL — NO gating on HWCFG2.msi_en
    }
}

when(io.reg.o_reg_errinfo_v.asBool && io.reg.o_reg_errcfg_ie.asBool) {
    when(io.reg.o_reg_errinfo_ttype === 1.U && !entry_attribute.sire) {
      io.int := true.B
    }.elsewhen(io.reg.o_reg_errinfo_ttype === 2.U && !entry_attribute.siwe) {
      io.int := true.B
    }.otherwise {
      io.int := false.B
    }
}
